var esteiras_validas = ['esteira1', 'esteira2', 'esteira3', 'esteira4', 'esteira5'];
var esteira = msg.payload && msg.payload.esteira;
var temperatura = msg.payload && msg.payload.temperatura;
var umidade = msg.payload && msg.payload.umidade;

if (!esteira || esteiras_validas.indexOf(esteira) === -1) {
    msg.statusCode = 400;
    msg.payload = { erro: 'Campo esteira invalido ou ausente', valores_aceitos: esteiras_validas };
    return [null, msg];
}

msg.esteira = esteira;
msg.temperatura = (typeof temperatura === 'number') ? temperatura : '';
msg.umidade = (typeof umidade === 'number') ? umidade : '';
return [msg, null];

// Troque esse caminho se quiser salvar em outro lugar.
// A PASTA precisa existir (o arquivo, se nao existir, e criado sozinho).
const CAMINHO_CSV = 'C:\\woodscan\\contagem.csv';
const CABECALHO = 'data,turno,esteira,timestamp,temperatura,umidade\n';

var agora = new Date();
var hora = agora.getHours();
var turno;
if (hora >= 6 && hora < 14) turno = 'manha';
else if (hora >= 14 && hora < 22) turno = 'tarde';
else turno = 'noite';

var data = agora.toISOString().slice(0, 10);
var timestamp = agora.toISOString();

try {
    if (!fs.existsSync(CAMINHO_CSV)) {
        fs.writeFileSync(CAMINHO_CSV, CABECALHO);
    }
    var linha = [data, turno, msg.esteira, timestamp, msg.temperatura, msg.umidade].join(',') + '\n';
    fs.appendFileSync(CAMINHO_CSV, linha);
} catch (erro) {
    node.error('Falha ao gravar CSV: ' + erro.message, msg);
    msg.statusCode = 500;
    msg.payload = { erro: 'Falha ao gravar no arquivo CSV' };
    return msg;
}

msg.payload = {
    esteira: msg.esteira, turno: turno, data: data, timestamp: timestamp,
    temperatura: msg.temperatura, umidade: msg.umidade,
    status: 'lamina registrada em CSV'
};
return msg;
